import * as Expressions from './expressions.model';

export class AclExpression {
	public aclExpressionId: number | null = null;
	public aclExpression?: string;
	public expression: Expressions.NonLeafExpression;

	constructor() {
		const exp: Expressions.OrExpression = new Expressions.OrExpression();
		exp.addCriteria();
		this.expression = exp;
	}
}