import { AfterViewInit, ChangeDetectorRef, Component, ElementRef, EventEmitter, inject, Input, OnInit, Output, ViewChild } from '@angular/core';
import { ControlContainer, FormGroup, UntypedFormGroup } from '@angular/forms';
import { MessageService } from 'espd-common/i18n';
import { AclComponentService } from './acl.component.service';
import { CriteriaFormModel } from './expression.form-model';
import { AttributeMappingList } from './user-attribute.model';

@Component({
	selector: 'espd-expression-criteria',
	templateUrl: 'expression-criteria.component.html',
	styleUrls: ['expression-criteria.component.scss'],
	standalone: false
})
export class ExpressionCriteriaComponent implements OnInit, AfterViewInit {

	public static smallBreakpoint = 400; // px

	@Input()
	public isSingleItem = false;

	@Output()
	public readonly remove: EventEmitter<UntypedFormGroup> = new EventEmitter<UntypedFormGroup>();

	@ViewChild('criteriaContainer')
	private criteriaContainer!: ElementRef<HTMLElement>;

	public formGroup!: FormGroup<CriteriaFormModel>;
	public isSmall = false;

	private _parent = inject(ControlContainer, { host: true, skipSelf: true });
	private cdr = inject(ChangeDetectorRef);
	private aclComponentService = inject(AclComponentService);
	public messageService = inject(MessageService);

	public ngOnInit(): void {
		this.formGroup = this._parent.control as UntypedFormGroup;
	}

	public ngAfterViewInit(): void {
		this.startObserving();
	}

	public get attributeMappings(): AttributeMappingList {
		return this.aclComponentService.resolvedAttributeMappings;
	}

	public removeSelf(): void {
		this.remove.emit(this.formGroup);
	}

	// Replace with container query once the feature is readily available in supported browsers
	private startObserving() {
		const ro = new ResizeObserver(entries => {
			for (const entry of entries) {
				this.isSmall = entry.contentRect.width <= ExpressionCriteriaComponent.smallBreakpoint;
				this.cdr.detectChanges();
			}
		});

		ro.observe(this.criteriaContainer.nativeElement);
	}
}