import { HttpClient } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { ApplicationConfig } from 'espd-common/config';
import { Observable, ReplaySubject } from 'rxjs';
import { AttributeMappingList } from './user-attribute.model';

@Injectable()
export class UserAttributeService {
	private attributeSubject: ReplaySubject<AttributeMappingList> = new ReplaySubject<AttributeMappingList>(1);
	public readonly attributeMappings: Observable<AttributeMappingList> = this.attributeSubject.asObservable();

	constructor() {
		const http = inject(HttpClient);
		const config = inject(ApplicationConfig);

		if (config.userAttributePath) {
			http.get<AttributeMappingList>(config.userAttributePath).subscribe(data => {
				this.attributeSubject.next(data);
				this.attributeSubject.complete();
			});
		} else {
			console.error('No user attribute path configured!');
		}
	}
}