import { Component, inject, Input } from '@angular/core';
import * as Expressions from '../expressions.model';
import { AttributeMappingList } from '../user-attribute.model';
import { UserAttributeService } from '../user-attribute.service';


@Component({
	selector: 'espd-acl-read-only',
	template: `<espd-non-leaf-expression-read-only [expression]="expression" [attributeMappings]="attributeMappings" />`,
	styles: [`:host {
			display: block;
		}`],
	standalone: false
})
export class AclReadonlyComponent {

	@Input()
	public expression!: Expressions.NonLeafExpressionImpl;

	public attributeMappings: Record<string, string> = {};

	constructor() {
		const userAttributeService = inject(UserAttributeService);
		userAttributeService.attributeMappings.subscribe((mappings: AttributeMappingList) => {
			for (const mapping of mappings) {
				this.attributeMappings[mapping.key] = mapping.value;
			}
		});
	}
}