import { Component, EventEmitter, inject, Input, Output } from '@angular/core';
import { UntypedFormArray, UntypedFormGroup } from '@angular/forms';
import { EspdFormGroup } from 'espd-common/forms/api';
import { AclComponentService } from './acl.component.service';
import { AclService } from './acl.service';
import { NonLeafExpressionFormModel } from './expression.form-model';
import * as Expressions from './expressions.model';

@Component({
	selector: 'espd-non-leaf-expression',
	templateUrl: 'non-leaf-expression.component.html',
	styleUrls: ['non-leaf-expression.component.scss'],
	standalone: false
})
export class NonLeafExpressionComponent {

	@Input()
	public isTopLevel = false;

	@Input()
	public expressionForm!: EspdFormGroup<NonLeafExpressionFormModel>;

	@Output()
	public readonly remove: EventEmitter<UntypedFormGroup> = new EventEmitter<UntypedFormGroup>();

	public Expressions = Expressions;

	private aclComponentService = inject(AclComponentService);

	get leafChildren(): UntypedFormArray { // used in template
		return this.expressionForm.get('leafChildren') as UntypedFormArray;
	}

	get nonLeafChildren(): UntypedFormArray { // used in template
		return this.expressionForm.get('nonLeafChildren') as UntypedFormArray;
	}

	get numControls(): number {
		let count = 0;
		if (this.leafChildren) {
			count += this.leafChildren.controls.length;
		}
		if (this.nonLeafChildren) {
			count += this.nonLeafChildren.controls.length;
		}
		return count;
	}

	public removeSelf(): void {
		this.remove.emit(this.expressionForm);
	}

	public setType(newType: string): void {
		this.expressionForm.controls.type.setValue(newType);
	}

	public addGroup(): void {
		const orExpression = new Expressions.OrExpression();
		orExpression.addCriteria();
		this.nonLeafChildren.push(AclService.buildFormGroup(orExpression));
	}

	public addCriteria(): void {
		this.leafChildren.push(AclService.criteriaToFormGroup(
			new Expressions.PersonAttributeExpression(),
			{
				required: this.aclComponentService.isRequired
			}
		));
	}

	public removeCriteria(group: UntypedFormGroup): void {
		if (this.leafChildren.length > 1) {
			const index: number = this.leafChildren.controls.indexOf(group);
			if (index >= 0) {
				this.leafChildren.removeAt(index);
				this.expressionForm.markAsDirty();
			}
		}
	}

	public removeExpressionGroup(group: UntypedFormGroup): void {
		if (this.nonLeafChildren.length > 0) {
			const index: number = this.nonLeafChildren.controls.indexOf(group);
			if (index >= 0) {
				this.nonLeafChildren.removeAt(index);
			}
		}
	}
}