import { Component, Injector, Input, OnChanges, forwardRef, inject } from '@angular/core';
import { EspdAbstractInputDirective, EspdFormGroup, espdAbstractInputComponentInjectionToken } from 'espd-common/forms/api';
import { AclComponentService } from './acl.component.service';
import { NonLeafExpressionFormModel } from './expression.form-model';
import { AttributeMappingList } from './user-attribute.model';

@Component({
	selector: 'espd-acl',
	template: `
		<espd-input-scaffold>
			<espd-non-leaf-expression [expressionForm]="control" [isTopLevel]="true" />
		</espd-input-scaffold>`,
	providers: [
		{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => AclComponent) },
		AclComponentService
	],
	standalone: false
})
export class AclComponent extends EspdAbstractInputDirective<EspdFormGroup<NonLeafExpressionFormModel>> implements OnChanges {

	@Input()
	public attributeMappings?: AttributeMappingList;

	constructor() {
		super(inject(Injector));
		const aclComponentService = inject(AclComponentService);
		aclComponentService.attributeMappingAccessor = () => this.attributeMappings;
		aclComponentService.requiredAccessor = () => this.required;
	}

	public focus(_target: 'control' | 'container' = 'control'): void {
		throw new Error('Method not implemented.');
	}
}