import { inject, Injectable } from '@angular/core';
import { AttributeMappingList } from './user-attribute.model';
import { UserAttributeService } from './user-attribute.service';

type AttributeMappingAccessor = () => AttributeMappingList | undefined;
type RequiredAccessor = () => boolean;

@Injectable()
export class AclComponentService {

	private attributeMappings: AttributeMappingList = [];

	private _attributeMappingAccessor?: AttributeMappingAccessor;
	set attributeMappingAccessor(accessor: AttributeMappingAccessor) {
		this._attributeMappingAccessor = accessor;
	}

	private _requiredAccessor?: RequiredAccessor;
	set requiredAccessor(accessor: RequiredAccessor) {
		this._requiredAccessor = accessor;
	}

	constructor() {
		inject(UserAttributeService).attributeMappings.subscribe(mappings => {
			this.attributeMappings = mappings;
		});
	}

	public get resolvedAttributeMappings(): AttributeMappingList {
		return this._attributeMappingAccessor?.() ?? this.attributeMappings;
	}

	public get isRequired(): boolean {
		return this._requiredAccessor?.() ?? false;
	}
}