import { Component, Input } from '@angular/core';

import * as Expressions from '../expressions.model';

@Component({
	selector: 'espd-non-leaf-expression-read-only',
	templateUrl: 'non-leaf-expression-read-only.component.html',
	styleUrls: ['non-leaf-expression-read-only.component.scss'],
	standalone: false
})
export class NonLeafExpressionReadonlyComponent {

	@Input()
	public expression!: Expressions.NonLeafExpressionImpl;

	@Input()
	public attributeMappings: Record<string, string> = {};

	public Expressions = Expressions;

	public get isAndExpression(): boolean {
		return this.expression._class === Expressions.AndExpression._class;
	}
}