import { FormArray, FormControl, FormGroup, Validators } from '@angular/forms';
import { CriteriaFormModel, NonLeafExpressionFormModel, SimpleNonLeafExpressionFormModel } from './expression.form-model';

import { EspdFormArray, EspdFormControl, EspdFormGroup } from 'espd-common/forms/api';
import { EspdValidators } from 'espd-common/forms/validators';
import * as Expressions from './expressions.model';

export interface CriteriaOptions {
	required: boolean
}

export class AclService {

	public static buildFormGroup(expression: Expressions.NonLeafExpression, opts: CriteriaOptions = { required: true }): EspdFormGroup<NonLeafExpressionFormModel> {
		return this.nonLeafToFormGroup((this.parseExpression(expression) as Expressions.NonLeafExpressionImpl), opts);
	}

	public static getExpressionFromFormModel(formModel: SimpleNonLeafExpressionFormModel, cleanForSave = true): Expressions.NonLeafExpressionImpl {
		return this.getNonLeafExpressionFromFormModel(formModel, cleanForSave);
	}

	public static convertToImpl(expression: Expressions.NonLeafExpression): Expressions.NonLeafExpressionImpl | null {
		return this.parseExpression(expression) as Expressions.NonLeafExpressionImpl;
	}

	public static criteriaToFormGroup(exp: Expressions.PersonAttributeExpression, opts: CriteriaOptions = { required: true }): EspdFormGroup<CriteriaFormModel> {
		const keyControl: EspdFormControl = new EspdFormControl(exp.key, opts.required ? Validators.required : null);

		return new EspdFormGroup<CriteriaFormModel>({
			key: keyControl,
			negated: new EspdFormControl(exp.negated) as FormControl<boolean>,
			value: new EspdFormControl<string>(exp.value, EspdValidators.conditional(() => keyControl.value !== null, Validators.required)) as FormControl<string>
		});
	}

	private static getNonLeafExpressionFromFormModel(formModel: SimpleNonLeafExpressionFormModel, cleanForSave = true): Expressions.NonLeafExpressionImpl {
		let expression: Expressions.NonLeafExpressionImpl;

		const type: string = formModel.type;
		switch (type) {
			case Expressions.AndExpression._class:
				expression = new Expressions.AndExpression();
				break;
			case Expressions.OrExpression._class:
				expression = new Expressions.OrExpression();
				break;
			default:
				throw new Error('Form model does not represent an expression');
		}

		formModel.leafChildren
			.map(leaf => new Expressions.PersonAttributeExpression(leaf.key, leaf.value, leaf.negated || false))
			.forEach(leaf => expression.addChild(leaf));

		formModel.nonLeafChildren
			.map(node => this.getNonLeafExpressionFromFormModel(node, cleanForSave))
			.forEach(leaf => expression.addChild(leaf));

		if (cleanForSave) {
			delete expression.leafChildren; // not used server-side
			delete expression.nonLeafChildren;
		}

		return expression;
	}

	private static nonLeafToFormGroup(exp: Expressions.NonLeafExpressionImpl, opts: CriteriaOptions): EspdFormGroup<NonLeafExpressionFormModel> {
		const leafFormGroups: FormGroup<CriteriaFormModel>[] = exp.leafChildren!.map(leaf => this.criteriaToFormGroup(leaf, opts));
		const nonLeafFormGroups: FormGroup<NonLeafExpressionFormModel>[] = exp.nonLeafChildren!.map(node => this.nonLeafToFormGroup(node, opts));

		return new EspdFormGroup<NonLeafExpressionFormModel>({
			leafChildren: new FormArray<FormGroup<CriteriaFormModel>>(leafFormGroups),
			nonLeafChildren: new EspdFormArray<FormGroup<NonLeafExpressionFormModel>>(nonLeafFormGroups),
			type: new EspdFormControl(exp._class) as FormControl<string>
		});
	}

	private static parseExpression(inputExpression: Expressions.IExpression): Expressions.IExpression | null {
		let expression = null;
		if (inputExpression != null) {
			switch (inputExpression._class) {
				case Expressions.AndExpression._class:
					expression = new Expressions.AndExpression();
					this.populateChildren((inputExpression as Expressions.NonLeafExpressionImpl), expression);
					break;
				case Expressions.OrExpression._class:
					expression = new Expressions.OrExpression();
					this.populateChildren((inputExpression as Expressions.NonLeafExpressionImpl), expression);
					break;
				case Expressions.PersonAttributeExpression._class:
					// eslint-disable-next-line no-case-declarations
					const attributeExpression: Expressions.PersonAttributeExpression = inputExpression as Expressions.PersonAttributeExpression;
					expression = new Expressions.PersonAttributeExpression(attributeExpression.key, attributeExpression.value, attributeExpression.negated || false);
					break;
			}
		}
		return expression;
	}

	private static populateChildren(inputExpression: Expressions.NonLeafExpressionImpl, expression: Expressions.NonLeafExpressionImpl) {
		if (inputExpression.children && inputExpression.children.length > 0) {
			for (const child of inputExpression.children) {
				const parsed = this.parseExpression(child);
				if (parsed) {
					expression.addChild(parsed);
				}
			}
		}
	}
}