export interface IExpression {
	_class: string;
}

export interface NonLeafExpression extends IExpression {
	_class: string;
	children: IExpression[];
}

export abstract class NonLeafExpressionImpl implements NonLeafExpression {
	public _class = '';
	public children: IExpression[];
	public leafChildren?: PersonAttributeExpression[];
	public nonLeafChildren?: NonLeafExpressionImpl[];

	constructor() {
		this.children = [];
		this.leafChildren = [];
		this.nonLeafChildren = [];
	}

	public addGroup(): void {
		const orExpression = new OrExpression();
		orExpression.addCriteria();
		this.addChild(orExpression);
	}

	public addCriteria(): void {
		this.addChild(new PersonAttributeExpression());
	}

	public addChild(child: IExpression): void {
		this.children.push(child);
		if (child instanceof NonLeafExpressionImpl) {
			this.nonLeafChildren!.push(child);
		} else {
			this.leafChildren!.push((child as PersonAttributeExpression));
		}
	}

	public removeChild(child: IExpression): void {
		let index = this.children.indexOf(child);
		if (index >= 0) {
			this.children.splice(index, 1);
		}
		if (child instanceof NonLeafExpressionImpl) {
			index = this.nonLeafChildren!.indexOf(child);
			if (index >= 0) {
				this.nonLeafChildren!.splice(index, 1);
			}
		} else {
			index = this.leafChildren!.indexOf((child as PersonAttributeExpression));
			if (index >= 0) {
				this.leafChildren!.splice(index, 1);
			}
		}
	}
}

export class AndExpression extends NonLeafExpressionImpl {
	public static _class = 'edu.iu.es.espd.tam.permission.AndExpression';
	public _class: string = AndExpression._class;
}

export class OrExpression extends NonLeafExpressionImpl {
	public static _class = 'edu.iu.es.espd.tam.permission.OrExpression';
	public _class: string = OrExpression._class;
}

export class PersonAttributeExpression implements IExpression {
	public static _class = 'edu.iu.es.espd.tam.permission.PersonAttributeExpression';
	public _class: string = PersonAttributeExpression._class;

	constructor(public key: string | null = null, public value: string | null = null, public negated = false) { }
}